function buildCyberAnimalItemDetails(lang) {
  const template = CYBER_ANIMAL_STORY_TEMPLATES[lang] || CYBER_ANIMAL_STORY_TEMPLATES.en
  const lines = CYBER_ANIMAL_STORY_LINES[lang] || []
  return Object.fromEntries(CYBER_ANIMAL_STORY_BASE.map(([slug, name, emoji], index) => {
    const storyLines = lines[index] || cyberAnimalFallbackLines(lang, name, index)
    return [`metamarket_info_item_cyber_animals_${slug}_details`, template(name, storyLines, emoji)]
  }))
}

const METAMARKET_CYBER_ANIMAL_ITEM_DETAILS = {
  en: buildCyberAnimalItemDetails('en'),
  ru: buildCyberAnimalItemDetails('ru'),
  uk: buildCyberAnimalItemDetails('uk'),
  es: buildCyberAnimalItemDetails('es'),
  zh: buildCyberAnimalItemDetails('zh'),
  ar: buildCyberAnimalItemDetails('ar'),
  tr: buildCyberAnimalItemDetails('tr'),
}

