function getHeroStoryFlavor(lang, index) {
  const set = HERO_STORY_FLAVOR[lang] || HERO_STORY_FLAVOR.en
  return {
    paths: [set.paths[index % set.paths.length]],
    artifacts: [set.artifacts[(index * 3 + 2) % set.artifacts.length]],
    destinies: [set.destinies[(index * 5 + 4) % set.destinies.length]],
  }
}

