function heroDetailSentence(value) {
  const text = String(value || '').trim()
  if (!text) return ''
  return text.charAt(0).toUpperCase() + text.slice(1)
}

function heroDetailLines(profile, lang, index) {
  const copy = HERO_DETAIL_COPY[lang] || HERO_DETAIL_COPY.en
  const labels = copy.labels
  const line = profile.line[lang] || profile.line.en
  const flavor = getHeroStoryFlavor(lang, index)
  return [
    `✦ ${profile.name}. ${heroDetailSentence(line)}. ${copy.text.intro}`,
    `◆ ${labels.visual}: ${copy.text.visual(profile.name, line, flavor)}`,
    `◇ ${labels.origin}: ${copy.text.origin(profile.name, flavor)}`,
    `✧ ${labels.function}: ${copy.text.function(profile.name)}`,
    `⬡ ${labels.future}: ${copy.text.future(profile.name, flavor)}`,
    `◌ ${labels.economy}: ${copy.text.economy(profile.name)}`,
    `◈ ${labels.owner}: ${copy.text.owner(profile.name)} ${profile.emoji}`,
  ]
}

function buildHeroItemDetails(lang) {
  const legacyTemplates = HERO_STORY_TEMPLATES[lang] || HERO_STORY_TEMPLATES.en
  const legacyCloser = HERO_STORY_CLOSERS[lang] || HERO_STORY_CLOSERS.en
  void legacyTemplates
  void legacyCloser
  return Object.fromEntries(HERO_STORY_BASE.map((profile, index) => [
    `metamarket_info_item_heroes_${profile.slug}_details`,
    heroDetailLines(profile, lang, index).join('\n\n'),
  ]))
}

const METAMARKET_HERO_ITEM_DETAILS = {
  en: buildHeroItemDetails('en'),
  ru: buildHeroItemDetails('ru'),
  uk: buildHeroItemDetails('uk'),
  es: buildHeroItemDetails('es'),
  zh: buildHeroItemDetails('zh'),
  ar: buildHeroItemDetails('ar'),
  tr: buildHeroItemDetails('tr'),
}

