function metaSpaceSentence(text) {
  if (!text) return ''
  return text.charAt(0).toUpperCase() + text.slice(1)
}

function metaSpaceProfileFields(profile, copy) {
  if (copy.fieldSet === 'ru') {
    return {
      form: profile.ruForm,
      origin: profile.ruOrigin,
      ability: profile.ruAbility,
      future: profile.ruFuture,
      owner: profile.ruOwner,
    }
  }
  return {
    form: profile.enForm,
    origin: profile.enOrigin,
    ability: profile.enAbility,
    future: profile.enFuture,
    owner: profile.enOwner,
  }
}

function metaSpaceDetailLines(profile, lang) {
  const copy = META_SPACE_DETAIL_COPY[lang] || META_SPACE_DETAIL_COPY.en
  const labels = copy.labels
  const fields = metaSpaceProfileFields(profile, copy)
  return [
    '✦ ' + profile.name + '. ' + metaSpaceSentence(fields.form) + '. ' + metaSpaceSentence(fields.origin) + '.',
    '◆ ' + labels.visual + ': ' + copy.text.visual,
    '◇ ' + labels.origin + ': ' + copy.text.origin,
    '✧ ' + labels.function + ': ' + fields.ability + '.',
    '⬡ ' + labels.future + ': ' + fields.future + '.',
    '◌ ' + labels.economy + ': ' + copy.text.economy(profile.name),
    '◈ ' + labels.owner + ': ' + fields.owner + '. ' + copy.text.owner + ' ' + profile.emoji,
  ]
}

function buildMetaSpaceItemDetails(lang) {
  const out = {}
  METAMARKET_META_SPACE_ITEM_PROFILES.forEach((profile) => {
    out['metamarket_info_item_meta_space_' + profile.slug + '_details'] = metaSpaceDetailLines(profile, lang).join('\n\n')
  })
  return out
}

const METAMARKET_META_SPACE_ITEM_DETAILS = {
  en: buildMetaSpaceItemDetails('en'),
  ru: buildMetaSpaceItemDetails('ru'),
  uk: buildMetaSpaceItemDetails('uk'),
  es: buildMetaSpaceItemDetails('es'),
  zh: buildMetaSpaceItemDetails('zh'),
  ar: buildMetaSpaceItemDetails('ar'),
  tr: buildMetaSpaceItemDetails('tr'),
}

