function realEstateSentence(text) {
  if (!text) return ''
  return text.charAt(0).toUpperCase() + text.slice(1)
}

function realEstateProfileFields(profile, copy) {
  if (copy.fieldSet === 'ru') {
    return {
      form: profile.ruForm,
      origin: profile.ruOrigin,
      ability: profile.ruAbility,
      future: profile.ruFuture,
      owner: profile.ruOwner,
    }
  }
  return {
    form: profile.enForm,
    origin: profile.enOrigin,
    ability: profile.enAbility,
    future: profile.enFuture,
    owner: profile.enOwner,
  }
}

function realEstateDetailLines(profile, lang) {
  const copy = REAL_ESTATE_DETAIL_COPY[lang] || REAL_ESTATE_DETAIL_COPY.en
  const labels = copy.labels
  const fields = realEstateProfileFields(profile, copy)
  return [
    '✦ ' + copy.opening(profile.name),
    '◆ ' + labels.visual + ': ' + realEstateSentence(fields.form) + '.',
    '◇ ' + labels.origin + ': ' + realEstateSentence(fields.origin) + '.',
    '✧ ' + labels.function + ': ' + realEstateSentence(fields.ability) + '.',
    '⬡ ' + labels.future + ': ' + realEstateSentence(fields.future) + '.',
    '◌ ' + labels.economy + ': ' + realEstateSentence(fields.owner) + '.',
    '◈ ' + labels.owner + ': ' + copy.ownerTail(profile.name) + ' ' + profile.emoji,
  ]
}

