function buildRealEstateItemDetails(lang) {
  const translated = METAMARKET_REAL_ESTATE_ITEM_TRANSLATED_DETAILS[lang]
  if (translated) return translated
  const out = {}
  METAMARKET_REAL_ESTATE_ITEM_PROFILES.forEach((profile) => {
    out['metamarket_info_item_real_estate_' + profile.slug + '_details'] = realEstateDetailLines(profile, lang).join('\n\n')
  })
  return out
}

const METAMARKET_REAL_ESTATE_ITEM_DETAILS = {
  en: buildRealEstateItemDetails('en'),
  ru: buildRealEstateItemDetails('ru'),
  uk: buildRealEstateItemDetails('uk'),
  es: buildRealEstateItemDetails('es'),
  zh: buildRealEstateItemDetails('zh'),
  ar: buildRealEstateItemDetails('ar'),
  tr: buildRealEstateItemDetails('tr'),
}

