function pickMetaResourceLine(lines, index, salt) {
  return lines[(index * 7 + salt * 11) % lines.length]
}

function buildMetaResourceItemDetails(lang) {
  const copy = META_RESOURCE_DETAIL_COPY[lang] || META_RESOURCE_DETAIL_COPY.en
  const out = {}
  METAMARKET_META_RESOURCE_ITEM_PROFILES.forEach((profile, index) => {
    const short = profile.short[lang] || profile.short.en
    const shortClean = short.replace(/[.。]+$/u, '')
    const stem = `metamarket_info_item_meta_resources_${profile.slug}`
    out[`${stem}_description`] = `${profile.name}: ${copy.descriptionSuffix}`
    out[`${stem}_details`] = [
      `✦ ${profile.name}. ${short} ${pickMetaResourceLine(copy.tones, index, 1)}`,
      `◆ ${copy.labels[0]}: ${pickMetaResourceLine(copy.origins, index, 2)} ${profile.name} ${copy.fingerprint}`,
      `◇ ${copy.labels[1]}: ${pickMetaResourceLine(copy.vectors, index, 3)} ${copy.path} ${copy.nature.replace('{short}', shortClean)}`,
      `✧ ${copy.labels[2]}: ${pickMetaResourceLine(copy.economy, index, 4)} ${copy.component.replace('{name}', profile.name)}`,
      `◈ ${copy.labels[3]} / ${copy.labels[4]}: ${profile.name}. ${pickMetaResourceLine(copy.economy, index, 6)} ${pickMetaResourceLine(copy.vectors, index, 8)} 💠`,
    ].join('\n\n')
  })
  return out
}

const METAMARKET_META_RESOURCE_ITEM_DETAILS = {
  en: buildMetaResourceItemDetails('en'),
  ru: buildMetaResourceItemDetails('ru'),
  uk: buildMetaResourceItemDetails('uk'),
  es: buildMetaResourceItemDetails('es'),
  zh: buildMetaResourceItemDetails('zh'),
  ar: buildMetaResourceItemDetails('ar'),
  tr: buildMetaResourceItemDetails('tr'),
}

