function applyTechniqueTemplate(text, profile, replacements = {}) {
  return String(text || '')
    .split('{name}')
    .join(profile.name)
    .split('{kind}')
    .join(replacements.kind ?? profile.kind)
    .split('{origin}')
    .join(replacements.origin ?? profile.origin)
    .split('{vector}')
    .join(replacements.vector ?? profile.vector)
    .split('{style}')
    .join(replacements.style ?? profile.style)
}

function techniqueVariant(lang, key, index, profile, fallback) {
  const set = TECHNIQUE_DETAIL_VARIANTS[lang] || TECHNIQUE_DETAIL_VARIANTS.en
  const list = set[key] || []
  const value = list.length ? list[index % list.length] : fallback
  return applyTechniqueTemplate(value, profile)
}

function techniqueLocalizedKind(lang, copy, profile) {
  const localizedPurpose = TECHNIQUE_LOCALIZED_PURPOSES[lang]?.[profile.slug]
  if (localizedPurpose) return localizedPurpose
  if (copy.profileKind) return applyTechniqueTemplate(copy.profileKind, profile)
  return copy.genericKind || profile.kind
}

function techniqueLocalizedTail(lang, key, profile, kind) {
  const tails = {
    uk: {
      origin: `Для ${profile.name} цей шар задає окрему технічну біографію, а не дубль сусідньої машини.`,
      vector: `Саме тому сценарій ${profile.name} має власний маршрут застосування, темп і майбутню вагу.`,
      future: `${profile.name} залишає в MetaMarket окремий серійний слід із власною історією руху.`,
    },
    es: {
      origin: `Para ${profile.name}, esta capa crea una biografía técnica propia y no una copia de otra máquina.`,
      vector: `Por eso el escenario de ${profile.name} conserva ruta, tempo y peso futuro independientes.`,
      future: `${profile.name} deja en MetaMarket una memoria serial separada con su propia historia de movimiento.`,
    },
    zh: {
      origin: `对 ${profile.name} 而言，这一层形成独立技术传记，而不是相邻机器的复制。`,
      vector: `因此 ${profile.name} 保留自己的路线、节奏与未来权重。`,
      future: `${profile.name} 在 MetaMarket 中留下独立序列记忆和自己的运动历史。`,
    },
    ar: {
      origin: `بالنسبة إلى ${profile.name}، تصنع هذه الطبقة سيرة تقنية خاصة لا نسخة من آلة مجاورة.`,
      vector: `لذلك يحتفظ سيناريو ${profile.name} بمساره وإيقاعه ووزنه المستقبلي المستقل.`,
      future: `يترك ${profile.name} في MetaMarket ذاكرة تسلسلية منفصلة وتاريخ حركة خاصاً.`,
    },
    tr: {
      origin: `${profile.name} için bu katman komşu bir makinenin kopyası değil, ayrı bir teknik biyografidir.`,
      vector: `Bu yüzden ${profile.name} senaryosu kendi rotasını, temposunu ve gelecek ağırlığını korur.`,
      future: `${profile.name}, MetaMarket içinde ayrı seri iz ve kendine ait hareket tarihi bırakır.`,
    },
  }
  return tails[lang]?.[key] || ''
}

function buildTechniqueItemDetails(lang) {
  const copy = TECHNIQUE_DETAIL_COPY[lang] || TECHNIQUE_DETAIL_COPY.en
  const out = {}
  METAMARKET_TECHNIQUE_ITEM_PROFILES.forEach((profile, index) => {
    const localized = Boolean(copy.localizedTechnique)
    const kind = localized ? techniqueLocalizedKind(lang, copy, profile) : (copy.kinds[profile.kind] || copy.kinds.rover)
    const origin = localized ? techniqueVariant(lang, 'origin', index + 1, profile, copy.sentences.origin) : (copy.origins[profile.origin] || copy.origins.frontierField)
    const vector = localized ? techniqueVariant(lang, 'vector', index + 2, profile, copy.sentences.vector) : (copy.vectors[profile.vector] || copy.vectors.scout)
    const style = localized ? techniqueVariant(lang, 'visual', index, profile, copy.sentences.visual) : (copy.styles[profile.style] || copy.styles.steel)
    const tier = localized ? techniqueVariant(lang, 'future', index + 3, profile, copy.sentences.future) : (copy.tiers[profile.tier] || copy.tiers.rare)
    const intro = copy.intros[index % copy.intros.length]
      .split('{name}')
      .join(profile.name)
      .split('{kind}')
      .join(kind)
    out[`metamarket_info_item_technique_${profile.slug}_description`] = `${profile.name}: ${kind}.`
    out[`metamarket_info_item_technique_${profile.slug}_details`] = [
      intro,
      localized
        ? `◆ ${copy.labels[0]}: ${style}`
        : `◆ ${copy.labels[0]}: ${style}. ${techniqueVariant(lang, 'visual', index, profile, copy.sentences.visual)}`,
      localized
        ? `◇ ${copy.labels[1]}: ${origin} ${techniqueLocalizedTail(lang, 'origin', profile, kind)}`
        : `◇ ${copy.labels[1]}: ${origin} ${techniqueVariant(lang, 'origin', index + 1, profile, copy.sentences.origin)}`,
      localized
        ? `✧ ${copy.labels[2]}: ${vector} ${techniqueLocalizedTail(lang, 'vector', profile, kind)}`
        : `✧ ${copy.labels[2]}: ${vector} ${techniqueVariant(lang, 'vector', index + 2, profile, copy.sentences.vector)}`,
      localized
        ? `⬡ ${copy.labels[3]}: ${tier} ${techniqueLocalizedTail(lang, 'future', profile, kind)}`
        : `⬡ ${copy.labels[3]}: ${tier} ${techniqueVariant(lang, 'future', index + 3, profile, copy.sentences.future)}`,
      `◈ ${copy.labels[4]}: ${techniqueVariant(lang, 'owner', index + 4, profile, copy.owner)} ${profile.emoji}`,
    ].join('\n\n')
  })
  return out
}

const METAMARKET_TECHNIQUE_ITEM_DETAILS = {
  en: buildTechniqueItemDetails('en'),
  ru: buildTechniqueItemDetails('ru'),
  uk: buildTechniqueItemDetails('uk'),
  es: buildTechniqueItemDetails('es'),
  zh: buildTechniqueItemDetails('zh'),
  ar: buildTechniqueItemDetails('ar'),
  tr: buildTechniqueItemDetails('tr'),
}


