function miscellaneousDetailPick(list, index, salt) {
  if (!Array.isArray(list) || list.length === 0) return ''
  return list[(index * 7 + salt) % list.length]
}

function miscellaneousDetailFill(text, profile, kind) {
  return String(text || '')
    .split('{name}').join(profile.name)
    .split('{kind}').join(kind)
    .split('{purpose}').join(kind)
}

function miscellaneousDetailKind(copy, profile) {
  const base = METAMARKET_MISCELLANEOUS_BASE_KINDS[profile.kind]
  if (base && typeof copy.kindIndex === 'number') return base[copy.kindIndex] || base[0]
  return copy.lead || 'unique MetaMarket item'
}

function miscellaneousDetailPurpose(lang, profile, fallback) {
  const purpose = METAMARKET_MISCELLANEOUS_PURPOSES[profile.slug]
  if (!purpose) return fallback
  if (purpose[lang]) return purpose[lang]
  return fallback
}

function miscellaneousDetailTrace(profile, index) {
  return 'MSC-' + String(index + 1).padStart(2, '0') + '-' + profile.slug.replace(/_/g, '-').toUpperCase()
}

