function miscellaneousDetailCapitalize(text) {
  const value = String(text || '').trim()
  if (!value) return ''
  return value.charAt(0).toLocaleUpperCase() + value.slice(1)
}

function miscellaneousDetailSentence(text) {
  const value = String(text || '').trim()
  if (!value) return ''
  return miscellaneousDetailCapitalize(value)
}

