function miscellaneousDetailPersonalize(lang, profile, purpose, section) {
  const dict = METAMARKET_MISCELLANEOUS_DETAIL_PERSONALITY[lang] || METAMARKET_MISCELLANEOUS_DETAIL_PERSONALITY.en
  const template = dict[section] || ''
  return miscellaneousDetailFill(template, profile, purpose)
}

function buildMiscellaneousItemDetails(lang) {
  const copy = METAMARKET_MISCELLANEOUS_DETAIL_COPY[lang] || METAMARKET_MISCELLANEOUS_DETAIL_COPY.en
  const out = {}
  METAMARKET_MISCELLANEOUS_ITEM_PROFILES.forEach((profile, index) => {
    const kind = miscellaneousDetailKind(copy, profile)
    const purpose = miscellaneousDetailPurpose(lang, profile, kind)
    const stem = 'metamarket_info_item_miscellaneous_' + profile.slug
    out[stem + '_description'] = miscellaneousDetailFill(copy.description, profile, purpose)
    const opening = miscellaneousDetailFill(miscellaneousDetailPick(copy.openings, index, 1), profile, purpose)
    const visual = miscellaneousDetailFill(miscellaneousDetailPick(copy.visuals, index, 2), profile, purpose)
    const origin = miscellaneousDetailFill(miscellaneousDetailPick(copy.origins, index, 3), profile, purpose)
    const vector = miscellaneousDetailFill(miscellaneousDetailPick(copy.vectors, index, 4), profile, purpose)
    const future = miscellaneousDetailFill(miscellaneousDetailPick(copy.futures, index, 5), profile, purpose)
    const owner = miscellaneousDetailFill(miscellaneousDetailPick(copy.owners, index, 6), profile, purpose)
    const zhVisualTail = lang === 'zh' ? ' ' + miscellaneousDetailFill(miscellaneousDetailPick(copy.visuals, index, 3), profile, purpose) : ''
    const zhOriginTail = lang === 'zh' ? ' ' + miscellaneousDetailFill(miscellaneousDetailPick(copy.origins, index, 4), profile, purpose) : ''
    const zhVectorTail = lang === 'zh' ? ' ' + miscellaneousDetailFill(miscellaneousDetailPick(copy.vectors, index, 5), profile, purpose) : ''
    const zhFutureTail = lang === 'zh' ? ' ' + miscellaneousDetailFill(miscellaneousDetailPick(copy.futures, index, 6), profile, purpose) : ''
    const zhOwnerTail = lang === 'zh' ? ' ' + miscellaneousDetailFill(miscellaneousDetailPick(copy.owners, index, 7), profile, purpose) : ''
    out[stem + '_details'] = [
      '\u2726 ' + profile.name + '. ' + miscellaneousDetailCapitalize(purpose) + '. ' + miscellaneousDetailSentence(opening + miscellaneousDetailLanguageExpansion(lang, profile, purpose, 'opening')),
      '\u25c6 ' + copy.labels[0] + ': ' + miscellaneousDetailSentence(visual + zhVisualTail) + ' ' + miscellaneousDetailPersonalize(lang, profile, purpose, 'visual'),
      '\u25c7 ' + copy.labels[1] + ': ' + miscellaneousDetailSentence(origin + zhOriginTail) + ' ' + miscellaneousDetailPersonalize(lang, profile, purpose, 'origin'),
      '\u2727 ' + copy.labels[2] + ': ' + miscellaneousDetailSentence(vector + zhVectorTail) + ' ' + miscellaneousDetailPersonalize(lang, profile, purpose, 'vector'),
      '\u2b21 ' + copy.labels[3] + ': ' + miscellaneousDetailSentence(future + zhFutureTail) + ' ' + miscellaneousDetailPersonalize(lang, profile, purpose, 'future'),
      '\u25c8 ' + copy.labels[4] + ': ' + miscellaneousDetailSentence(owner + zhOwnerTail) + ' ' + miscellaneousDetailPersonalize(lang, profile, purpose, 'owner') + ' ' + profile.emoji,
    ].join('\\n\\n')
  })
  return out
}

const METAMARKET_MISCELLANEOUS_ITEM_DETAILS = {
  en: buildMiscellaneousItemDetails('en'),
  ru: buildMiscellaneousItemDetails('ru'),
  uk: buildMiscellaneousItemDetails('uk'),
  es: buildMiscellaneousItemDetails('es'),
  zh: buildMiscellaneousItemDetails('zh'),
  ar: buildMiscellaneousItemDetails('ar'),
  tr: buildMiscellaneousItemDetails('tr'),
}

